//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			HE_SP_Select                                                                                                                                                                                                                                                                   
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2025-08-27		William Veim			Initial release
//	1.0.1				2025-09-25		William Veim			ReWork
//	1.0.2				2025-11-13		William Veim			Initialise normal setpoint desc
//	1.0.3				2025-11-13		William Veim			Added copy of unit to setpoint (only when used)
//
//==============================================================================================================================
//
// 		FUNCTIONALITY:
// 		Retriving data for current setpoint
//
//==============================================================================================================================

(*************************************************************************
 *	INITIALIZE
 *************************************************************************)
 
SP_Normal.Process_Desc:='Normal setpoint';
SP_Normal.Sts_InUse:=TRUE;
SP_Select:=LIMIT(MN:=UINT#0, In:=SP_Select, MX:=UINT#4);

Clear(SP_InUse_CNT.Wrd);
SP_InUse_CNT.Bit[0]:=SP_Normal.Sts_InUse;
SP_InUse_CNT.Bit[0]:=SP_Value1.Sts_InUse;
SP_InUse_CNT.Bit[1]:=SP_Value2.Sts_InUse;
SP_InUse_CNT.Bit[2]:=SP_Value3.Sts_InUse;
SP_InUse_CNT.Bit[3]:=SP_Value4.Sts_InUse;

SP_NumberUsed:= BitCnt(In:=SP_InUse_CNT.Wrd);
SP_OnlyOneUsed:=SP_NumberUsed = 1;
SP_MultipleUsed:=SP_NumberUsed > 1;

IF SP_OnlyOneUsed THEN
	SP_Select:=0;
END_IF;

(*************************************************************************
 *	SELECT SETPOINT TO USE
 *************************************************************************)

//Retrive setpoint info
CASE SP_Select OF
	
	0://Normal setpoint
	SP_Actual:=SP_Normal;
	SP_Normal.Process_Unit:=PV_Unit;
	
	1: //Setpoint 1
	SP_Actual:=SP_Value1;
	SP_Value1.Process_Unit:=PV_Unit;
	
	2: //Setpoint 1
	SP_Actual:=SP_Value2;
	SP_Value2.Process_Unit:=PV_Unit;
	
	3: //Setpoint 1
	SP_Actual:=SP_Value3;
	SP_Value3.Process_Unit:=PV_Unit;
	
	4: //Setpoint 1
	SP_Actual:=SP_Value4;
	SP_Value4.Process_Unit:=PV_Unit;
	
END_CASE;
